public int findMinFibonacciNumbers(int k) {
    int count = 0;
    List<Integer> fibNumbers = new ArrayList<>();
    int a = 1, b = 1;
    fibNumbers.add(a);
    fibNumbers.add(b);

    // Generate Fibonacci numbers up to k
    while (b <= k) {
        int next = a + b;
        a = b;
        b = next;
        fibNumbers.add(b);
    }

    // Subtract the largest Fibonacci number less than or equal to k
    while (k > 0) {
        int largest = fibNumbers.stream().filter(x -> x <= k).max(Integer::compare).get();
        k -= largest;
        count++;
    }

    return count;
}

