public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    StringBuilder sb = new StringBuilder();
    boolean negative = n < 0;
    n = Math.abs(n);
    for (int i = 0; i < String.valueOf(n).length(); i++) {
        if (i > 0 && (String.valueOf(n).length() - i) % 3 == 0) {
            sb.append(".");
        }
        sb.append(String.valueOf(n).charAt(i));
    }
    return negative ? "-" + sb.toString() : sb.toString();
}

