public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    int[] dp = new int[1 << n];
    dp[0] = 1;

    for (int i = 1; i < 1 << n; i++) {
        for (int j = 0; j < n; j++) {
            if ((i & (1 << j)) > 0) {
                int prev = i ^ (1 << j);
                boolean valid = true;
                for (int k = 0; k < n; k++) {
                    if ((prev & (1 << k)) > 0) {
                        if (!isPerfectSquare(A[j] + A[k])) {
                            valid = false;
                            break;
                        }
                    }
                }
                if (valid) {
                    dp[i] += dp[prev];
                }
            }
        }
    }

    return dp[(1 << n) - 1];
}

