public static int calculateUniqueSum(int[] nums) {
    int uniqueSum = 0;
    for (int i = 0; i < nums.length; i++) {
        boolean isUnique = true;
        for (int j = 0; j < nums.length; j++) {
            if (i != j && nums[i] == nums[j]) {
                isUnique = false;
                break;
            }
        }
        if (isUnique) {
            uniqueSum += nums[i];
        }
    }
    return uniqueSum;
}

